const base = require('./base');
const forms = require('./forms');
const legacy = require('./legacy');

// Each configuration is written before a spread of another module's
// `configs`; the later one wins where that module writes the same key.
module.exports = {
  rules: {},
  configs: {
    // `base` writes no `browser`: this one is the plugin's.
    browser: { globals: { ky: 'readonly' } },
    ...base.configs,
    // `forms` writes its own `forms`, which wins over this one.
    forms: { globals: {} },
    ...forms.configs,
    // `legacy` is not there to read: this one is taken, and the spread said.
    legacy: { globals: { axios: 'readonly' } },
    ...legacy.configs,
  },
};
